const response = await fetch("https://apibara.tech/api/v1/vehicle-auction/vehicles", {
  method: "GET",
  headers: {
    Accept: "application/json",
    "X-API-Key": process.env.APIBARA_API_KEY,
  },
});
if (!response.ok) throw new Error(`HTTP ${response.status}`);
console.log(await response.json());

